import{_ as d,a0 as n,w as r,s as o,I as i,x as t,a1 as l,A as u,ao as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"有了新家的 Budgie 发布了第一个新版本 | LCTT x X-CMD","titleTemplate":false,"description":"有了新家的 Budgie 发布了第一个新版本 | LCTT (202203) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"有了新家的 Budgie 发布了第一个新版本 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"有了新家的 Budgie 发布了第一个新版本 | LCTT (202203) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202203/20220307 Budgie 10.6 is Here as its First Release Under the New Organization","title":"有了新家的 Budgie 发布了第一个新版本","tag":"202203","desc":""},"relativePath":"202203/20220307 Budgie 10.6 is Here as its First Release Under the New Organization.md","filePath":"[post].md"}'),a={name:"202203/20220307 Budgie 10.6 is Here as its First Release Under the New Organization.md"};function g(m,e,f,b,B,w){const s=n("Link");return r(),o("div",null,[e[22]||(e[22]=i("h1",{id:"有了新家的-budgie-发布了第一个新版本",tabindex:"-1"},[t("有了新家的 Budgie 发布了第一个新版本 "),i("a",{class:"header-anchor",href:"#有了新家的-budgie-发布了第一个新版本","aria-label":"Permalink to “有了新家的 Budgie 发布了第一个新版本”"},"​")],-1)),e[23]||(e[23]=i("blockquote",null,[i("p",null,"在一个新组织的管理下， Budgie 10.6 发布在一个新的仓库，进行了一些令人印象深刻的改进。")],-1)),e[24]||(e[24]=i("p",null,[i("img",{src:"https://i0.wp.com/news.itsfoss.com/wp-content/uploads/2022/03/budgie-10-6-release.png?w=1200&ssl=1",alt:""})],-1)),e[25]||(e[25]=i("p",null,"早在今年一月份，Solus 的前联合负责人 Joshua Strobl 在离开 Solus 后去 SerpentOS 工作的传闻成为了新闻头条。",-1)),i("p",null,[e[1]||(e[1]=t("你可以在我们的 ",-1)),l(s,{href:"https://news.itsfoss.com/solus-co-lead-resign-budgie-serpent/"},{default:u(()=>[...e[0]||(e[0]=[t("原始报道",-1)])]),_:1}),e[2]||(e[2]=t(" 中阅读更多关于它的内容。",-1))]),e[26]||(e[26]=p('<p>然而，他仍然想为 Budgie 桌面环境工作，所以他（在一个新的仓库中）复刻了这个项目，并成立了 Buddies Of Budgie 组织。三个月后，这个组织变化后的第一个版本已经到来，我们将在这里看看它。</p><h3 id="budgie-10-6-的新变化" tabindex="-1">Budgie 10.6 的新变化 <a class="header-anchor" href="#budgie-10-6-的新变化" aria-label="Permalink to “Budgie 10.6 的新变化”">​</a></h3><p><img src="https://i0.wp.com/news.itsfoss.com/wp-content/uploads/2022/03/budgie-10.61.png?resize=1568%2C882&amp;ssl=1" alt=""></p><p>鉴于这是自上述组织结构调整后的第一个版本，它的功能变化相当少。尽管如此，这里有一个关于新内容的总体总结：</p><ul><li>完善的主题设计</li><li>新的通知系统</li><li>代码重新格式化</li></ul><p>在最新更新的公告中，Joshua 还提到：</p><blockquote><p>Budgie 10.6 旨在弥合 Budgie 传统的“下游”消费者和开发组织本身之间的鸿沟，使像 Ubuntu Budgie 这样的下游能够更密切地参与到它的开发当中。</p><p>作为我们的核心支柱之一，即成为一个平台而不是一个产品，Budgie 10.6 和未来的 Budgie 版本的目标是提供一个宏观世界，或一组最小的紧密耦合的组件，并将生态系统的其余部分留给下游消费者的决策和价值观，无论它是发行版还是终端用户。</p></blockquote><p>所以，如果你担心 Budgie 桌面环境在分裂后的发展，这应该能让你放心了。</p><h4 id="主题改进" tabindex="-1">主题改进 <a class="header-anchor" href="#主题改进" aria-label="Permalink to “主题改进”">​</a></h4><p><img src="https://i0.wp.com/news.itsfoss.com/wp-content/uploads/2022/03/budgie-10.6-theming.jpg?w=1159&amp;ssl=1" alt=""></p><p>看起来，这个版本的主题改进基本上是为了提高一致性，做一些细节的改变，以获得现代的外观。</p><p>例如，边框圆角已经应用于一些桌面元素，统一的间距，统一的小工具的颜色方案，以及对 GTK 主题支持的其他改进。</p><p>从我对这个版本的亲身体验来看，这些变化是细微的，但也能让人感受到，而且确实感觉到它们使 Budgie 更能与 GNOME 和 KDE 等桌面相提并论。</p><h4 id="新的通知系统" tabindex="-1">新的通知系统 <a class="header-anchor" href="#新的通知系统" aria-label="Permalink to “新的通知系统”">​</a></h4><p>虽然不是很明显，但 Budgie 现在已经有了一个新的通知系统。其最大的影响是它现在已经从位于屏幕右侧的面板 Raven 中移出。</p><p>因此，其他 Budgie 组件现在可以使用新的通知系统。一个提到的例子是“解锁未来在图标任务列表中支持通知徽章的能力”。</p><p>同样，虽然此变化很小，但确实打开了未来的可能性，希望我们能在未来的版本中看到这些带来的变化。</p><h4 id="其他改进措施" tabindex="-1">其他改进措施 <a class="header-anchor" href="#其他改进措施" aria-label="Permalink to “其他改进措施”">​</a></h4><p>Budgie 10.6 一些其他的变化包括：</p><ul><li>使用制表符而不是空格，对一些代码进行了常规的重新格式化。</li><li>重新引入对 GNOME 40 的支持，以启用 Ubuntu LTS 支持。</li><li>将 GNOME 控制中心重新命名为 Budgie 控制中心。</li><li>修复了扩大 Raven 缩略图导致 Raven 本身调整大小的问题。</li></ul>',20)),i("p",null,[e[4]||(e[4]=t("如果你想了解更多，你可以在 ",-1)),l(s,{href:"https://github.com/BuddiesOfBudgie/budgie-desktop/releases/tag/v10.6"},{default:u(()=>[...e[3]||(e[3]=[t("GitHub",-1)])]),_:1}),e[5]||(e[5]=t(" 上找到发布公告，以获得完整的新功能列表。",-1))]),i("ul",null,[i("li",null,[l(s,{href:"https://github.com/BuddiesOfBudgie/budgie-desktop/releases/"},{default:u(()=>[...e[6]||(e[6]=[t("Budgie 10.6",-1)])]),_:1})])]),e[27]||(e[27]=i("h3",{id:"获得-budgie-10-6",tabindex:"-1"},[t("获得 Budgie 10.6 "),i("a",{class:"header-anchor",href:"#获得-budgie-10-6","aria-label":"Permalink to “获得 Budgie 10.6”"},"​")],-1)),e[28]||(e[28]=i("p",null,"如果你想获得 Budgie 10.6，最好是先等待你的发行版将其打包。如果你使用的是 Arch，这可能需要不到一周的时间，而 Ubuntu 及其衍生版本则需要更长时间。",-1)),e[29]||(e[29]=i("p",null,"对于那些喜欢冒险的人来说，你也可以尝试编译它，但如果你愿意尝试，你可能已经知道如何做了。",-1)),e[30]||(e[30]=i("p",null,"总的来说，Budgie 10.6 看起来是一个值得关注的版本，特别是考虑到其重大的组织变化。",-1)),e[31]||(e[31]=i("p",null,"你对 Budgie 10.6 的变化有什么看法？请在下面的评论中告诉我们吧！",-1)),e[32]||(e[32]=i("hr",null,null,-1)),i("p",null,[e[8]||(e[8]=t("via: ",-1)),l(s,{href:"https://news.itsfoss.com/budgie-10-6-release/"},{default:u(()=>[...e[7]||(e[7]=[t("https://news.itsfoss.com/budgie-10-6-release/",-1)])]),_:1})]),i("p",null,[e[13]||(e[13]=t("作者：",-1)),l(s,{href:"https://news.itsfoss.com/author/jacob/"},{default:u(()=>[...e[9]||(e[9]=[t("Jacob Crume",-1)])]),_:1}),e[14]||(e[14]=t(" 选题：",-1)),l(s,{href:"https://github.com/lujun9972"},{default:u(()=>[...e[10]||(e[10]=[t("lujun9972",-1)])]),_:1}),e[15]||(e[15]=t(" 译者：",-1)),l(s,{href:"https://github.com/wxy"},{default:u(()=>[...e[11]||(e[11]=[t("wxy",-1)])]),_:1}),e[16]||(e[16]=t(" 校对：",-1)),l(s,{href:"https://github.com/wxy"},{default:u(()=>[...e[12]||(e[12]=[t("wxy",-1)])]),_:1})]),i("p",null,[e[19]||(e[19]=t("本文由 ",-1)),l(s,{href:"https://github.com/LCTT/TranslateProject"},{default:u(()=>[...e[17]||(e[17]=[t("LCTT",-1)])]),_:1}),e[20]||(e[20]=t(" 原创编译，",-1)),l(s,{href:"https://linux.cn/"},{default:u(()=>[...e[18]||(e[18]=[t("Linux中国",-1)])]),_:1}),e[21]||(e[21]=t(" 荣誉推出",-1))])])}const k=d(a,[["render",g]]);export{C as __pageData,k as default};
